const cases=[
{id:'colares',title:'Operação Prato',location:'Colares, PA',region:'Brasil',year:'1977',tag:'Documentação oficial',scene:'forest',summary:'Uma investigação militar sobre relatos de luzes no Pará.',detail:'Em 1977, a Força Aérea Brasileira investigou relatos de luzes e fenômenos aéreos na região de Colares, no Pará. A investigação ficou conhecida como Operação Prato. Parte dos documentos foi disponibilizada no Arquivo Nacional.',evidence:'Os documentos registram uma investigação e relatos de observadores. Eles não demonstram, por si só, uma origem extraterrestre para os fenômenos descritos.',source:'https://www.gov.br/arquivonacional/pt-br',sourceName:'Arquivo Nacional · acervo sobre OVNIs'},
{id:'nimitz',title:'Encontro do Nimitz',location:'Pacífico, EUA',region:'Internacional',year:'2004',tag:'Registro reconhecido',scene:'ocean',summary:'Pilotos da Marinha e um objeto descrito como “Tic Tac”.',detail:'Em novembro de 2004, aviadores ligados ao grupo do USS Nimitz relataram um objeto branco sobre o oceano Pacífico. O caso ficou conhecido pela descrição “Tic Tac”. Um vídeo infravermelho associado ao encontro foi oficialmente divulgado pelo Departamento de Defesa dos EUA em 2020.',evidence:'O reconhecimento oficial da gravação confirma sua procedência militar; não confirma as interpretações sobre velocidade, tecnologia ou origem do objeto.',source:'https://www.aaro.mil/UAP-Cases/Official-UAP-Imagery/',sourceName:'AARO · imagens oficiais de UAP'},
{id:'roswell',title:'Incidente de Roswell',location:'Novo México, EUA',region:'Internacional',year:'1947',tag:'Explicação oficial',scene:'desert',summary:'Destroços, versões conflitantes e um marco da cultura ufológica.',detail:'Em julho de 1947, destroços encontrados perto de Roswell geraram comunicados e especulações. Décadas depois, relatórios da Força Aérea dos EUA associaram os materiais ao projeto Mogul, que utilizava balões para detectar testes nucleares.',evidence:'A explicação oficial é o projeto Mogul. As narrativas sobre uma nave e ocupantes extraterrestres não têm comprovação pública verificável.',source:'https://www.af.mil/The-Roswell-Report/',sourceName:'Força Aérea dos EUA · The Roswell Report'},
{id:'noite',title:'Noite Oficial dos OVNIs',location:'Sudeste, Brasil',region:'Brasil',year:'1986',tag:'Documentação oficial',scene:'night',summary:'Relatos de pilotos e detecções por radar em uma noite brasileira.',detail:'Na noite de 19 de maio de 1986, relatos de objetos luminosos e registros de radar motivaram a decolagem de aeronaves militares no Brasil. O episódio tornou-se conhecido como a Noite Oficial dos OVNIs e gerou documentação militar.',evidence:'Relatos e registros devem ser analisados em seu contexto. O fato de um objeto permanecer não identificado não determina sua origem.',source:'https://www.gov.br/arquivonacional/pt-br',sourceName:'Arquivo Nacional · documentação de OVNIs'},
{id:'phoenix',title:'Luzes de Phoenix',location:'Arizona, EUA',region:'Internacional',year:'1997',tag:'Relatos e controvérsia',scene:'city',summary:'Um conjunto de relatos de luzes observado por muitas pessoas.',detail:'Em 13 de março de 1997, moradores do Arizona relataram luzes em formação. Os relatos incluem diferentes horários e regiões. Parte das luzes registradas mais tarde foi atribuída a sinalizadores lançados em treinamento militar.',evidence:'É necessário distinguir os diferentes episódios daquela noite. Uma explicação para uma gravação não resolve automaticamente todos os relatos; os relatos também não comprovam uma nave.',source:'https://www.britannica.com/topic/unidentified-flying-object',sourceName:'Britannica · contexto sobre OVNIs'},
{id:'bluebook',title:'Projeto Blue Book',location:'Estados Unidos',region:'Internacional',year:'1952–1969',tag:'Arquivo histórico',scene:'mountain',summary:'O programa da Força Aérea americana para investigar OVNIs.',detail:'O Projeto Blue Book foi um programa da Força Aérea dos EUA que investigou relatos de objetos voadores não identificados entre 1952 e 1969. Seus documentos são mantidos pelo Arquivo Nacional dos Estados Unidos.',evidence:'O programa reuniu casos explicados e casos sem identificação. Sua conclusão institucional não encontrou evidência de veículos extraterrestres. Casos sem explicação não constituem prova de uma origem específica.',source:'https://www.archives.gov/research/military/air-force/ufos',sourceName:'National Archives · Project Blue Book'}
];
function readStore(key){try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v:[]}catch{return []}}
let favorites=readStore('orbita-favorites').filter(x=>typeof x==='string'),entries=readStore('orbita-entries').filter(x=>x&&typeof x.title==='string'&&typeof x.description==='string'),filter='todos';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Não foi possível salvar neste navegador.');return false}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200)}
function scene(type){let terrain=type==='ocean'?'<path d="M0 128q50-10 100 0t100 0t100 0t100 0v70H0" fill="#1b3540"/><path d="M0 147q50-8 100 0t100 0t100 0t100 0M0 165q40-5 80 0t80 0t80 0t80 0" stroke="#668e8c" stroke-opacity=".35" fill="none"/>':type==='desert'?'<path d="M0 145l60-17 55 13 80-27 90 30 80-5 40 20v50H0" fill="#736650"/><path d="M0 168q110-35 210-10t200-7v60H0" fill="#453f31"/>':type==='forest'?'<path d="M0 168l45-50 40 15 60-57 40 46 60-40 80 69 45-26 40 35v60H0" fill="#344738"/><path d="M0 177l20-49 20 49 20-65 24 65 20-50 21 50 25-64 28 64 30-42 23 42 24-75 32 75 24-54 22 54 24-45 28 45v35H0" fill="#14291e"/>':type==='city'?'<path d="M0 169h25v-25h30v10h22v-35h28v35h20v-15h27v-40h20v52h30v-23h34v38h30v-67h29v40h20v-15h26v35h40v-14h30v45H0" fill="#24302d"/><g fill="#c0a56d"><path d="M40 150h3v3h-3m48-20h3v3h-3m82 18h3v3h-3m110-27h3v3h-3m5 10h3v3h-3m48 17h3v3h-3"/></g>':'<path d="M0 178l65-62 40 29 60-61 70 67 36-35 100 63 40-30v55H0" fill="#2d3c35"/><path d="M145 106l20-22 26 25-23-8-9 10z" fill="#879a88" opacity=".5"/><path d="M0 187l95-30 100 21 85-18 120 29v30H0" fill="#15231c"/>';
let lights=type==='city'?'<g fill="#e6c99b"><circle cx="115" cy="75" r="2"/><circle cx="150" cy="68" r="2"/><circle cx="188" cy="64" r="2"/><circle cx="225" cy="70" r="2"/><circle cx="260" cy="78" r="2"/></g>':'<ellipse cx="218" cy="72" rx="'+(type==='ocean'?19:9)+'" ry="3" fill="#e2efd0"/><ellipse cx="218" cy="72" rx="24" ry="10" fill="#d7f1ad" opacity=".07"/>';
return '<svg viewBox="0 0 400 210" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="sky-'+type+'" x2="0" y2="1"><stop stop-color="#111e22"/><stop offset="1" stop-color="'+(type==='desert'?'#716452':'#3c5144')+'"/></linearGradient></defs><rect width="400" height="210" fill="url(#sky-'+type+')"/><g fill="#c5d6bc" opacity=".5"><circle cx="33" cy="33" r=".8"/><circle cx="85" cy="56" r=".7"/><circle cx="166" cy="24" r=".8"/><circle cx="310" cy="44" r="1"/><circle cx="364" cy="75" r=".6"/><circle cx="267" cy="20" r=".6"/></g>'+lights+terrain+'</svg>'}
function renderCases(){const q=$('#search').value.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');const list=cases.filter(c=>(filter==='todos'||c.region===filter||(filter==='favoritos'&&favorites.includes(c.id)))&&[c.title,c.location,c.year].join(' ').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q));$('#cases').innerHTML=list.map(c=>'<article class="card"><div class="visual">'+scene(c.scene)+'<span class="label">'+esc(c.location.toUpperCase())+' · '+esc(c.year)+'</span><button class="save '+(favorites.includes(c.id)?'saved':'')+'" data-save="'+c.id+'" aria-label="'+(favorites.includes(c.id)?'Remover dos favoritos':'Salvar caso')+'" aria-pressed="'+favorites.includes(c.id)+'">'+(favorites.includes(c.id)?'★':'☆')+'</button></div><div class="card-body"><div class="case-meta"><span>'+esc(c.region.toUpperCase())+'</span><span>ARQUIVO / '+esc(c.year)+'</span></div><h3>'+esc(c.title)+'</h3><p>'+esc(c.summary)+'</p><div class="card-bottom"><span class="status">'+esc(c.tag)+'</span><button class="text-button" data-case="'+c.id+'">Explorar caso ↗</button></div></div></article>').join('');$('#empty').hidden=!!list.length}
$('#cases').addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const next=favorites.includes(save.dataset.save)?favorites.filter(x=>x!==save.dataset.save):[...favorites,save.dataset.save];if(persist('orbita-favorites',next)){favorites=next;renderCases()}return}const btn=e.target.closest('[data-case]');if(btn){const c=cases.find(x=>x.id===btn.dataset.case);$('#case-content').innerHTML='<div class="case-detail-label">'+esc(c.location)+' · '+esc(c.year)+'</div><h2>'+esc(c.title)+'</h2><p>'+esc(c.detail)+'</p><h3>O que as evidências permitem dizer</h3><p>'+esc(c.evidence)+'</p><p><a href="'+c.source+'" target="_blank" rel="noopener">'+esc(c.sourceName)+' ↗</a></p><p class="muted">As imagens dos cartões são ilustrações artísticas, não registros dos casos.</p>';$('#case-dialog').showModal()}});
$('.filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(b){filter=b.dataset.filter;document.querySelectorAll('.chip').forEach(x=>x.classList.toggle('active',x===b));renderCases()}});$('#search').addEventListener('input',renderCases);
function showView(view){if(!['inicio','guia','diario'].includes(view))view='inicio';document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==view);document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===view));if(view==='diario')renderEntries();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.nav').forEach(x=>x.addEventListener('click',()=>{location.hash=x.dataset.view}));window.addEventListener('hashchange',()=>showView(location.hash.slice(1)));$('#guide-link').onclick=()=>location.hash='guia';$('#explore').onclick=()=>$('#catalog').scrollIntoView({behavior:'smooth'});
function openObservation(){$('#observation-form').reset();const now=new Date();$('#observation-form').elements.date.value=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');$('#observation-form').elements.time.value=String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');$('#form-error').textContent='';$('#observation-dialog').showModal()}
$('#register').onclick=openObservation;$('#diary-add').onclick=openObservation;document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#observation-form').addEventListener('submit',e=>{e.preventDefault();const form=e.target;const data=Object.fromEntries(new FormData(form));if(!data.title.trim()||!data.place.trim()||!data.description.trim()){$('#form-error').textContent='Preencha título, local e descrição com texto.';return}const next=[{...data,title:data.title.trim(),place:data.place.trim(),description:data.description.trim(),id:(globalThis.crypto?.randomUUID?.() || Date.now().toString(36)+Math.random().toString(36).slice(2))},...entries];if(persist('orbita-entries',next)){entries=next;$('#observation-dialog').close();location.hash='diario';showView('diario');toast('Observação salva no seu diário.')}else $('#form-error').textContent='Armazenamento indisponível. Copie sua descrição antes de fechar.'});
function renderEntries(){$('#diary-count').textContent=entries.length;$('#entries').innerHTML=entries.length?entries.map(e=>'<article class="entry"><div class="entry-meta">'+esc(e.date)+' · '+esc(e.time)+' / '+esc(e.place)+'</div><h3>'+esc(e.title)+'</h3><p>'+esc(e.description)+'</p><button class="text-button" data-delete="'+esc(e.id)+'">Excluir registro</button></article>').join(''):'<div class="empty-diary"><div class="eyebrow" style="justify-content:center">NENHUMA OBSERVAÇÃO AINDA</div><h2>Todo registro começa com um olhar.</h2><p>Use “Nova observação” para começar seu caderno de campo.</p></div>';$('#export').disabled=!entries.length}
$('#entries').addEventListener('click',e=>{const b=e.target.closest('[data-delete]');if(b&&confirm('Excluir este registro do diário?')){const next=entries.filter(x=>x.id!==b.dataset.delete);if(persist('orbita-entries',next)){entries=next;renderEntries();toast('Registro excluído.')}}});
$('#export').onclick=()=>{if(!entries.length)return;const blob=new Blob([JSON.stringify({app:'Órbita',exportedAt:new Date().toISOString(),observations:entries},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='orbita-diario.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Cópia do diário exportada.')};
renderCases();renderEntries();showView(location.hash.slice(1));
